/**
 * An invitation is pending while it has not been accepted, revoked or
 * expired — the definition every seat count and listing must agree on.
 */
function pendingPredicate(orgId: OrgId, now: IsoTimestamp) {
  return and(
    orgPredicate(invitations.orgId, orgId),
    isNull(invitations.acceptedAt),
    isNull(invitations.revokedAt),
    gt(invitations.expiresAt, now),
  );
}

export async function listPendingInvitations(
  orgId: OrgId,
): Promise<readonly Invitation[]> {
  const rows = getDb()
    .select()
    .from(invitations)
    .where(pendingPredicate(orgId, toIsoTimestamp(new Date())))
    .orderBy(desc(invitations.createdAt))
    .all();

  return rows.map(toInvitation);
}

/**
 * A pending invitation for this address, if any — used to refuse a duplicate
 * invite. Case-insensitive because addresses are compared without regard to
 * letter case.
 */
export async function findPendingInvitationByEmail(
  orgId: OrgId,
  email: string,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        pendingPredicate(orgId, toIsoTimestamp(new Date())),
        eq(sql`lower(${invitations.email})`, email.toLowerCase()),
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

/**
 * Looks an invitation up for resending regardless of expiry — resending an
 * already-expired invitation is the usual reason to do it. Only accepted or
 * revoked invitations are excluded.
 */
export async function findResendableInvitation(
  orgId: OrgId,
  invitationId: InvitationId,
): Promise<Invitation | null> {
  const row = getDb()
    .select()
    .from(invitations)
    .where(
      and(
        orgPredicate(invitations.orgId, orgId),
        eq(invitations.id, invitationId),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
      ),
    )
    .get();
  return row ? toInvitation(row) : null;
}

