/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }
  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
    throw new Error("That invitation has expired");
  }

  const org = await orgRepo.findOrgById(invitation.orgId);
  if (!org || org.archivedAt !== null) {
    throw new Error("That workspace no longer exists");
  }

  const user = requireFound(await userRepo.findUserById(userId), "User", userId);
  if (user.email.toLowerCase() !== invitation.email.toLowerCase()) {
    throw new Error("This invitation was sent to a different email address");
  }

  const existing = await memberRepo.findMemberAnyStatus(invitation.orgId, userId);
  const now = toIsoTimestamp(new Date());

  const member =
    existing && existing.archivedAt === null
      ? existing
      : existing
        ? await memberRepo.reactivateMember(
            invitation.orgId,
            existing.id,
            invitation.role,
            invitation.invitedBy,
            now,
          )
        : await memberRepo.insertMember(
            invitation.orgId,
            userId,
            invitation.role,
            invitation.invitedBy,
          );

  await invitationRepo.markInvitationAccepted(invitation.orgId, invitation.id, now);

  if (!existing || existing.archivedAt !== null) {
    await emit("member.joined", {
      ...envelope(invitation.orgId, userId),
      memberId: member.id,
      userId,
      role: member.role,
    });
  }

  return member;
}

/**
 * Refuses a batch that names an address already covered — by a current
 * member or a still-pending invitation — or that names the same address
 * twice. The whole batch is refused; nothing is created for a bad batch.
 */
async function assertInvitesAreFresh(
  orgId: import("@/types/common").OrgId,
  invites: readonly { email: string; role: string }[],
): Promise<void> {
  const seen = new Set<string>();
  for (const invite of invites) {
    const key = invite.email.toLowerCase();
    if (seen.has(key)) {
      throw new Error(`${invite.email} is named more than once in this batch`);
    }
    seen.add(key);

    const existingUser = await userRepo.findUserByEmail(invite.email);
    if (existingUser) {
      const existingMember = await memberRepo.findMember(orgId, existingUser.id);
      if (existingMember) {
        throw new Error(`${invite.email} is already a member of this organization`);
      }
    }

    const pending = await invitationRepo.findPendingInvitationByEmail(
      orgId,
      invite.email,
    );
    if (pending) {
      throw new Error(`${invite.email} already has a pending invitation`);
    }
  }
}

